def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or 'target object'
    dest = nb.get('destination_type') or 'destination'
    verb = nb.get('required_verb') or needverb(nb.get('task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target item. Do not place it as the goal object; recover by setting it aside only if needed, then find the requested ' + target + '.'
    elif stage == 'transform' and verb:
        msg = 'Before final placement, use the admissible ' + verb + ' action on the ' + target + ' at the proper appliance or container. Do not put it at the destination yet.'
    elif stage == 'go_destination' and dest:
        msg = 'Carry the ' + target + ' to a ' + dest + ' and use the admissible put action there. Do not place it on unrelated surfaces.'
    elif stage == 'put_target' and dest:
        msg = 'Place the ' + target + ' in/on the ' + dest + ' using the admissible put action. After a correct put, do not loop on look or examine.'
    elif stage == 'take_target' and target:
        msg = 'A requested ' + target + ' is available here. Take it instead of continuing to search unrelated containers.'
    elif stage == 'find_target' and nb.get('placed_count', 0) > 0 and 'two' in (nb.get('task_type') or ''):
        msg = 'One ' + target + ' is already placed. Leave it there, find another ' + target + ', and use the same ' + dest + ' destination.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

