def hook(ctx, nb):
    tt = nb.get('task_type') or text(getv(ctx, 'task.task_type', ''))
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(tt)
    if not verb or not target:
        return None
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    if not act:
        return None
    admiss = [text(a) for a in (ctx.get('admissible') or [])]
    if act.startswith('put ') and target in act and dest and dest not in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested destination type. Carry the ' + target + ' to a ' + dest + ' and put it there instead.'}
    if act.startswith('put ') and target in act and dest in act and not nb.get('transformed'):
        return {'kind': 'block_and_prompt', 'message': 'Do not place the ' + target + ' yet. First use the admissible ' + verb + ' action, then put it at the ' + dest + '.'}
    if act in ('look', 'inventory') and nb.get('stage') == 'transform' and not nb.get('transformed') and any(a.startswith(verb + ' ') for a in admiss):
        return {'kind': 'block_and_prompt', 'message': 'A required ' + verb + ' action is available now. Use it on the ' + target + ' before looking, checking inventory, or placing the item.'}
    if nb.get('stage') == 'put_target' and act in ('look', 'examine') and (getv(ctx, 'predicates.same_action_repeated', False) or getv(ctx, 'predicates.same_observation_repeated', False) or getv(ctx, 'predicates.remaining_steps_low', False)):
        return {'kind': 'block_and_prompt', 'message': 'Avoid another look or examine loop. Continue with the next subgoal: find another target for two-object tasks, or finish placing the carried target.'}
    return None
